<?php get_header(); ens_breadcrumb('Catálogo'); ?><main class="ens-container ens-main"><div class="ens-page-head"><h1>Catálogo</h1><p><?php echo esc_html(wp_count_posts('ens_product')->publish); ?> productos<br>Calidad para hacer bien el trabajo</p></div><div class="ens-catalog-layout"><aside class="ens-filters"><h3>Categorías</h3><ul><li><a class="ens-selected" href="<?php echo esc_url(get_post_type_archive_link('ens_product')); ?>">Todos</a></li><?php $terms=get_terms(array('taxonomy'=>'ens_product_cat','hide_empty'=>true));foreach($terms as $term) echo '<li><a href="'.esc_url(get_term_link($term)).'">'.esc_html($term->name).'</a></li>'; ?></ul></aside><div><div class="ens-toolbar"><small>Mostrando productos</small><form method="get"><select class="ens-sort" name="orden" onchange="this.form.submit()"><option value="">Recomendados</option><option value="menor" <?php selected(isset($_GET['orden'])?sanitize_key($_GET['orden']):'','menor'); ?>>Precio menor</option><option value="mayor" <?php selected(isset($_GET['orden'])?sanitize_key($_GET['orden']):'','mayor'); ?>>Precio mayor</option></select></form></div><div class="ens-products"><?php $args=array('post_type'=>'ens_product','posts_per_page'=>-1);if(isset($_GET['orden']) && in_array($_GET['orden'],array('menor','mayor'),true)){$args['meta_key']='_ens_price';$args['orderby']='meta_value_num';$args['order']=$_GET['orden']==='menor'?'ASC':'DESC';}$q=new WP_Query($args);if($q->have_posts()):while($q->have_posts()):$q->the_post();ens_product_card(get_the_ID());endwhile;wp_reset_postdata();else:echo '<div class="ens-no-products"><strong>Todavía no hay productos cargados</strong><span>Agregalos desde WordPress en Productos.</span></div>';endif; ?></div></div></div></main><?php get_footer(); ?>
